import { test, expect } from '@playwright/test';
import fs from 'fs';
import path from 'path';

// DASHBOARD CONFIG
const DASHBOARD_URL = 'http://localhost:5173';
const REPORT_DIR = './test-results/dashboard-audit';

// Az összes menüpont ID-ja a navigation.tsx alapján
const NAV_ITEMS = [
  'neural-map', 'system-arch', 'cean', 'cloudflare', 'fleet_manager', 
  'chat', 'paios', 'phoenix', 'management', 'decomposer', 'tracks', 
  'incubator', 'knowledge', 'mcp', 'developer', 'edge', 'suggested-tasks', 
  'tests', 'enterprise-analytics', 'robotkez', 'tasks', 'python-workers', 
  'inventory', 'files', 'marketwatcher', 'settings'
];

test.describe('🚀 Brunella Dashboard Full UI Audit', () => {

  test.beforeAll(async () => {
    if (!fs.existsSync(REPORT_DIR)) {
      fs.mkdirSync(REPORT_DIR, { recursive: true });
    }
  });

  for (const navId of NAV_ITEMS) {
    test(`Audit Page: ${navId}`, async ({ page }) => {
      console.log(`\n--- Auditing: ${navId} ---`);

      // Hibák gyűjtése
      const consoleErrors: string[] = [];
      page.on('console', msg => {
        if (msg.type() === 'error') consoleErrors.push(msg.text());
      });

      const failedRequests: string[] = [];
      page.on('requestfailed', request => {
        failedRequests.push(`${request.method()} ${request.url()}: ${request.failure()?.errorText}`);
      });

      // 1. Navigáció az oldalra
      await page.goto(`${DASHBOARD_URL}`);
      // Várjunk a splash screenre
      await page.waitForTimeout(3000); 

      // Próbáljuk meg kinyitni a menüt és átváltani a tab-ra (vagy direkt URL-lel ha támogatja)
      // A Dashboard navigációja belső state-et használ, így szimuláljuk a kattintást az oldalsávon
      try {
        const sidebarLink = page.locator(`[data-nav-id="${navId}"], a:has-text("${navId}")`).first();
        if (await sidebarLink.isVisible()) {
          await sidebarLink.click();
        } else {
          // Fallback: Ha nem találjuk a linket, próbáljuk meg a belső navigációs logikát triggerelni a window-n keresztül
          await page.evaluate((id) => {
            // Ez feltételezi, hogy van valamilyen globális mód a tab váltásra teszteléshez
            console.log("Attempting manual tab switch to: " + id);
          }, navId);
        }
      } catch (e) {
        console.warn(`Could not find sidebar link for ${navId}, continuing with page content.`);
      }

      await page.waitForTimeout(1000);
      await page.screenshot({ path: path.join(REPORT_DIR, `${navId}_initial.png`) });

      // 2. Gombok keresése és tesztelése
      const buttons = page.locator('button, [role="button"]');
      const buttonCount = await buttons.count();
      console.log(`Found ${buttonCount} buttons on ${navId}`);

      // Csak az első pár gombot teszteljük automatikusan, hogy ne pörögjön végtelen ciklusba
      for (let i = 0; i < Math.min(buttonCount, 10); i++) {
        const btn = buttons.nth(i);
        if (await btn.isVisible() && await btn.isEnabled()) {
          const btnText = await btn.innerText();
          console.log(`  Clicking button: "${btnText || 'unnamed'}"`);

          try {
            await btn.click({ timeout: 2000 });
            await page.waitForTimeout(500); // Várjunk a reakcióra
          } catch (e) {
            console.error(`  Failed to click button ${i}: ${e.message}`);
          }
        }
      }

      // 3. Eredmények összegzése
      if (consoleErrors.length > 0) {
        console.error(`❌ FOUND ${consoleErrors.length} CONSOLE ERRORS on ${navId}:`);
        consoleErrors.forEach(err => console.error(`   - ${err}`));
      }

      if (failedRequests.length > 0) {
        console.error(`❌ FOUND ${failedRequests.length} FAILED NETWORK REQUESTS on ${navId}:`);
        failedRequests.forEach(req => console.error(`   - ${req}`));
      }

      expect(consoleErrors.length, `Console errors detected on ${navId}`).toBe(0);
      expect(failedRequests.length, `Network failures detected on ${navId}`).toBe(0);
    });
  }
});

