        failedRequests.forEach(req => console.error(`   - ${req}`));
      }

      expect(consoleErrors.length, `Console errors detected on ${navId}`).toBe(0);
      expect(failedRequests.length, `Network failures detected on ${navId}`).toBe(0);
    });
  }
});

