  status: string;
  phases: PipelinePhaseView[];
  createdAt: number;
  completedAt?: number;
  error?: string;
}

interface DevStatus {
  activeTasks: number;
  completedTasks: number;
  failedTasks: number;
  totalTasks: number;
}

interface HistoryEntry {
  taskId: string;
  task: string;
