interface TestRun {
  id: string;
  status: "passed" | "failed" | "running";
  duration: string;
  passed: number;
  failed: number;
  startedAt: string;
}

interface ChartData {
  date: string;
  passRate: number;
  passed: number;
  failed: number;
}

export function TestResultsWidget() {
  const [stats, setStats] = useState<TestStats | null>(null);
  const [recentRuns, setRecentRuns] = useState<TestRun[]>([]);
  const [chartData, setChartData] = useState<ChartData[]>([]);
  const [loading, setLoading] = useState(true);
  const [triggering, setTriggering] = useState(false);
  const [autoRefresh, setAutoRefresh] = useState(true);

  // Fetch stats
  const fetchStats = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/tests/stats");
      if (!response.ok) throw new Error("Failed to fetch stats");
      
      const data = await response.json() as TestStats;
      setStats(data);

      // Parse pass rate percentage
      const passRateNum = parseFloat(data.passRate);
      setChartData([
        {
          date: "7d Trend",
          passRate: passRateNum,
          passed: 0,
          failed: 0,
        },
      ]);
    } catch (error) {
      toast.error("Failed to load test statistics");
    } finally {
      setLoading(false);
    }
  };

  // Fetch recent runs
  const fetchRecentRuns = async () => {
    try {
      const response = await fetch("/api/tests/results?limit=10");
      if (!response.ok) throw new Error("Failed to fetch runs");
      
      const data = await response.json();
      setRecentRuns(data.runs || []);
    } catch (error) {
      toast.error("Failed to load recent test runs");
    }
  };

  // Trigger manual run
  const handleTriggerRun = async () => {
    try {
      setTriggering(true);
      const response = await fetch("/api/tests/run", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ triggerReason: "Manual trigger from dashboard" }),
      });

      if (!response.ok) throw new Error("Failed to trigger test run");

      const data = await response.json();
      toast.success(`Test run triggered: ${data.runId}`);
      
      // Refresh data after a short delay
      setTimeout(() => {
        fetchStats();
        fetchRecentRuns();
      }, 1000);
    } catch (error) {
      toast.error("Failed to trigger test run");
    } finally {
      setTriggering(false);
    }
  };

  // Initial load
  useEffect(() => {
    fetchStats();
    fetchRecentRuns();
  }, []);

  // Auto-refresh
  useEffect(() => {
    if (!autoRefresh) return;

    const interval = setInterval(() => {
      fetchStats();
      fetchRecentRuns();
    }, 5 * 60 * 1000); // 5 minutes

    return () => clearInterval(interval);
  }, [autoRefresh]);

  if (loading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-64 w-full" />
        <Skeleton className="h-32 w-full" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header with Actions */}
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Teszt Ütemezés (Test Scheduler)</h2>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              fetchStats();
              fetchRecentRuns();
            }}
            disabled={loading}
          >
            <RefreshCw className="h-4 w-4 mr-2" />
            Frissítés
          </Button>
          <Button
            onClick={handleTriggerRun}
            disabled={triggering}
            className="bg-blue-600 hover:bg-blue-700"
          >
            <Play className="h-4 w-4 mr-2" />
            {triggering ? "Futtatás..." : "Tesztek Futtatása"}
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-gray-600">
                Összes Futás
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-3xl font-bold">{stats.totalRuns}</div>
              <p className="text-xs text-gray-500 mt-1">lifetime</p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-gray-600">
                Pass Rate (7d)
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-3xl font-bold text-green-600">
                {stats.sevenDayPassRate}
              </div>
              <p className="text-xs text-gray-500 mt-1">most recent</p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-gray-600">
                Átlagos Futási Idő
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold flex items-center gap-2">
                <Clock className="h-5 w-5 text-orange-500" />
                {stats.averageDuration}
              </div>
              <p className="text-xs text-gray-500 mt-1">avg duration</p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-gray-600">
                Utolsó Futás
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold flex items-center gap-2">
                {stats.lastRunStatus === "passed" ? (
                  <CheckCircle className="h-5 w-5 text-green-500" />
                ) : (
                  <XCircle className="h-5 w-5 text-red-500" />
                )}
                <span className="capitalize">{stats.lastRunStatus}</span>
              </div>
              <p className="text-xs text-gray-500 mt-1">{stats.lastRunTime}</p>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Chart */}
      <Card>
        <CardHeader>
          <CardTitle>Pass Rate Trend (7 nap)</CardTitle>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={300}>
            <ComposedChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis yAxisId="left" label={{ value: "Pass Rate (%)", angle: -90, position: "insideLeft" }} />
              <YAxis yAxisId="right" orientation="right" label={{ value: "Test Count", angle: 90, position: "insideRight" }} />
              <Tooltip />
              <Legend />
              <Line
                yAxisId="left"
                type="monotone"
                dataKey="passRate"
                stroke="#10b981"
                strokeWidth={2}
                name="Sikeres arány (%)"
              />
              <Bar yAxisId="right" dataKey="passed" fill="#3b82f6" name="Sikeres" />
              <Bar yAxisId="right" dataKey="failed" fill="#ef4444" name="Sikertelen" />
            </ComposedChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>

      {/* Recent Runs Table */}
      <Card>
        <CardHeader>
          <CardTitle>Utolsó 10 Futás</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="border-b">
                <tr>
                  <th className="text-left py-2 px-4 font-medium">Státusz</th>
                  <th className="text-left py-2 px-4 font-medium">Sikeres</th>
                  <th className="text-left py-2 px-4 font-medium">Sikertelen</th>
                  <th className="text-left py-2 px-4 font-medium">Futási Idő</th>
                  <th className="text-left py-2 px-4 font-medium">Időpont</th>
                </tr>
              </thead>
              <tbody>
                {recentRuns.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="text-center py-4 text-gray-500">
                      Nincs korábbi futás
                    </td>
                  </tr>
                ) : (
                  recentRuns.map((run) => (
                    <tr key={run.id} className="border-b hover:bg-gray-50">
                      <td className="py-2 px-4">
                        <span
                          className={`px-2 py-1 rounded text-xs font-medium ${
                            run.status === "passed"
                              ? "bg-green-100 text-green-800"
                              : run.status === "failed"
                                ? "bg-red-100 text-red-800"
                                : "bg-yellow-100 text-yellow-800"
                          }`}
                        >
                          {run.status}
                        </span>
                      </td>
                      <td className="py-2 px-4">
                        <span className="text-green-600 font-medium">
                          {run.passed}
                        </span>
                      </td>
                      <td className="py-2 px-4">
                        <span className="text-red-600 font-medium">
                          {run.failed}
                        </span>
                      </td>
                      <td className="py-2 px-4">{run.duration}</td>
                      <td className="py-2 px-4 text-gray-500 text-xs">
                        {new Date(run.startedAt).toLocaleString("hu-HU")}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Auto-refresh Toggle */}
      <div className="flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          id="auto-refresh"
          checked={autoRefresh}
          onChange={(e) => setAutoRefresh(e.target.checked)}
          className="rounded"
        />
        <label htmlFor="auto-refresh">
          Auto-frissítés 5 percenként
        </label>
      </div>
    </div>
  );
}

import React from "react";
import { cn } from "@/lib/utils";
import { Layers, Shield, Ghost } from "lucide-react";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { navigationRegistry } from "@/lib/navigation";

interface DynamicSidebarProps {
  activeTab: string;
  onTabChange: (tab: string) => void;
}

export function DynamicSidebar({ activeTab, onTabChange }: DynamicSidebarProps) {
  const groups = navigationRegistry.getGroups();
  const items = navigationRegistry.getAllItems();

  const findItem = (id: string) => items.find(item => item.id === id);

  return (
    <aside className="w-[64px] lg:w-[260px] flex flex-col gap-4 py-4 z-10 transition-all duration-300 shrink-0">
      <div className="glass-panel rounded-2xl flex-1 flex flex-col overflow-hidden border-white/5">
        <div className="p-4 border-b border-white/5 flex items-center justify-between">
          <span className="text-[10px] font-bold text-zinc-500 tracking-widest uppercase hidden lg:inline">Primary Menu</span>
          <Layers size={14} className="text-zinc-500" />
        </div>
        
        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
          <Accordion type="multiple" defaultValue={["Core Systems", "AI & Agents"]} className="w-full">
            {groups.map((group) => (
              <AccordionItem value={group.title} key={group.title} className="border-none">
                <AccordionTrigger className="text-xs font-bold text-zinc-500 hover:text-zinc-200 uppercase tracking-wider px-3 py-2.5 rounded-xl hover:no-underline hover:bg-white/5">
                  <div className="flex items-center gap-3">
                    <group.icon size={14} />
                    <span className="hidden lg:inline">{group.title}</span>
                  </div>
                </AccordionTrigger>
                <AccordionContent className="pt-1 pb-2 space-y-1">
                  {group.items.map(itemId => {
                    const item = findItem(itemId);
                    if (!item) return null;
                    return (
                      <button
                        key={item.id}
                        onClick={() => onTabChange(item.id)}
                        className={cn(
                          "w-full flex items-center gap-3 rounded-xl px-3 py-2.5 transition-all duration-200 group relative",
                          "text-zinc-400 hover:text-zinc-100 hover:bg-white/5",
                          activeTab === item.id && "bg-primary/10 text-white border border-primary/20",
                        )}
                      >
                        <div className="w-4 h-4 flex items-center justify-center">
                          <item.icon size={16} className={cn( "shrink-0 transition-transform duration-300", activeTab === item.id ? "text-primary" : "text-zinc-500 group-hover:text-zinc-300" )} />
                        </div>
                        <span className="hidden lg:inline text-xs font-medium font-space tracking-wide">{item.label}</span>
                        {activeTab === item.id && (
                          <div className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-5 bg-primary rounded-r-full shadow-[0_0_10px] shadow-primary/50" />
                        )}
                      </button>
                    )
                  })}
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        </div>

        <div className="p-4 border-t border-white/5 bg-black/20">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-8 h-8 rounded-full bg-zinc-800 border border-white/10 flex items-center justify-center">
              <Shield size={14} className="text-primary" />
            </div>
            <div className="flex flex-col min-w-0 hidden lg:flex">
              <span className="text-[10px] font-bold text-white truncate uppercase">Master Admin</span>
              <span className="text-[9px] font-mono text-emerald-500/80">AUTHORIZED</span>
            </div>
          </div>
          <button className="w-full text-[10px] font-bold text-zinc-500 hover:text-white transition-colors flex items-center justify-between py-1 border-t border-white/5 pt-3">
            <span>DISCONNECT</span>
            <Ghost size={12} />
          </button>
        </div>
      </div>
    </aside>
  );
}

