      expect(foundTask, "A beküldött feladatnak meg kell jelennie a backend várólistáján").toBeDefined();
    } catch (e) {
      console.error("  ❌ ERROR: Could not connect to backend to verify task creation.");
      throw e;
    }
  });
});

