public async delegate(
  agentName: string,
  task: string,
  context?: Record<string, unknown>,
): Promise<TaskResult> {
  const taskId = (context as any)?.taskId;

  try {
    if (taskId) {
      await this.updateTaskStatus(taskId, "running");
    }

    const result = await this.executeAgentWithRetry(
      agentName,
      task,
      context,
    );

    if (taskId) {
      await this.updateTaskStatus(
        taskId,
        result.success ? "done" : "error",
        JSON.stringify(result.data || result.message),
      );
    }

    return result;
  } catch (error: any) {
    if (taskId) {
      await this.updateTaskStatus(taskId, "error", error.message);
    }
    throw error;
  }
}

