import { ChatProvider, ChatMode, ChatSendInput, ChatSendOutput } from "../types";
import { analyzeIntent } from "@/../../src/core/intentAnalyzer"; // Adjust path if needed
import * as api from "@/lib/apiService";

/**
 * Master Orchestrator Provider
 * Routes requests between Local Orchestrator and Cloudflare Edge Orchestrator
 * based on intent analysis.
 */
export class MasterOrchestratorProvider implements ChatProvider {
  readonly mode: ChatMode = "master_orchestrator";

  async send(args: ChatSendInput): Promise<ChatSendOutput> {
    const { text } = args;
    
    // 1. Analyze Intent
    const analysis = analyzeIntent(text);
    
    // 2. Delegate to correct target
    if (analysis.target === "edge") {
      try {
        const result = await api.submitCloudflareTask(text, { source: "master_orchestrator" });
        return {
          message: `[Edge] Feladat beküldve a Cloudflare orkesztrátornak (ID: ${result.taskId}).\n\nIndoklás: ${analysis.reasoning}`,
          executedBy: "CEAN Orchestrator",
          thoughts: analysis.reasoning,
          contextUsed: ["Cloudflare Edge Network"]
        };
      } catch (e: any) {
        return {
          message: `⚠️ Hiba az Edge delegálás során: ${e.message}. Megpróbálom helyben végrehajtani...`,
          executedBy: "System Fallback"
        };
      }
    }

    // 3. Default to Local Orchestrator
    try {
      const response = await api.executeAgent("orchestrator", text);
      return {
        message: response.data?.message || "A helyi orkesztrátor megkezdte a feladat végrehajtását.",
        executedBy: "Local Orchestrator",
        thoughts: analysis.reasoning,
        contextUsed: ["Local Workspace"]
      };
    } catch (e: any) {
      throw new Error(`Helyi orkesztrációs hiba: ${e.message}`);
    }
  }
}

export type ExecutionTarget = "local" | "edge";

export interface IntentAnalysis {
  target: ExecutionTarget;
  confidence: number;
  reasoning: string;
  originalTask: string;
}

const EDGE_KEYWORDS = [
  "edge", "cloud", "global", "cean", "pályázat", "kutatás", "research", "scrape", 
  "harvester", "deploy", "worker", "pályázatfigyelő", "grant", "ev hunter"
];

const LOCAL_KEYWORDS = [
  "local", "fájl", "file", "test", "teszt", "build", "typescript", "python", 
  "git", "commit", "local machine", "rendszer", "system", "számla", "invoice"
];

export function analyzeIntent(task: string): IntentAnalysis {
  const normalizedTask = task.toLowerCase();
  
  let edgeScore = 0;
  let localScore = 0;

  EDGE_KEYWORDS.forEach(kw => {
    if (normalizedTask.includes(kw)) edgeScore++;
  });

  LOCAL_KEYWORDS.forEach(kw => {
    if (normalizedTask.includes(kw)) localScore++;
  });

  // Default to local if no clear indicator
  let target: ExecutionTarget = "local";
  let confidence = 0.7;
  let reasoning = "Alapértelmezett helyi végrehajtás";

  if (edgeScore > localScore) {
    target = "edge";
    confidence = 0.8 + (Math.min(edgeScore, 2) * 0.1);
    reasoning = "Felhő/Edge specifikus kulcsszavak azonosítva";
  } else if (localScore > edgeScore) {
    target = "local";
    confidence = 0.8 + (Math.min(localScore, 2) * 0.1);
    reasoning = "Helyi rendszer műveletekre utaló kulcsszavak";
  } else if (edgeScore > 0 && localScore > 0) {
    // Conflict - prefer local for safety or edge if both mentioned
    target = "local";
    confidence = 0.5;
    reasoning = "Vegyes kulcsszavak, megerősítés javasolt";
  }

  return {
    target,
    confidence,
    reasoning,
    originalTask: task
  };
}

