import { OrchestratorChat } from './chat/OrchestratorChat';

/**
 * CEAN Primary Page: OrchestratorChat-focused
 * Other tabs (Workers, Tasks, Data) are available via future expansion
 */
export const CEANLayout = () => {
  return <OrchestratorChat />;
};

import { useEffect, useRef, useState } from 'react';
import { Send, Trash2, Copy } from 'lucide-react';
import { useCEANSocket } from '../hooks/useCEANSocket';
import { useChatHistory } from '../hooks/useChatHistory';
import { SOCKET_EVENTS, TASK_TEMPLATES, MAX_CHAT_MESSAGES } from '../utils/constants';
import { logInfo, logError } from '@/utils/logger';

interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
  taskId?: string;
}

export const OrchestratorChat = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [expandedTemplate, setExpandedTemplate] = useState<string | null>(null);
  const [sessionId, setSessionId] = useState<string>('');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { socket, connected, emit, on } = useCEANSocket();
  const chatHistory = useChatHistory();

  // Initialize session ID and load history
  useEffect(() => {
    let sid = sessionStorage.getItem('cean_session_id');
    if (!sid) {
      sid = `session-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
      sessionStorage.setItem('cean_session_id', sid);
    }
    setSessionId(sid);
    chatHistory.loadHistory(sid).catch((e) => logError('OrchestratorChat', `Failed to load history: ${e}`));
  }, [chatHistory]);

  // Sync loaded history to local messages state
  useEffect(() => {
    if (chatHistory.messages.length > 0) {
      setMessages(chatHistory.messages);
      logInfo('OrchestratorChat', `Loaded ${chatHistory.messages.length} messages from history`);
    }
  }, [chatHistory.messages]);

  // Auto-scroll to bottom
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages]);

  // Socket event listener
  useEffect(() => {
    if (!socket) return;

    const handleOrchestratorResponse = (data: unknown) => {
      try {
        const response = data as {
          taskId?: string;
          content?: string;
          error?: string;
        };
        
        if (response.error) {
          logError('OrchestratorChat', response.error);
          setMessages((prev) => [
            ...prev,
            {
              id: `msg-${Date.now()}`,
              role: 'assistant',
              content: `❌ Hiba: ${response.error}`,
              timestamp: Date.now(),
            },
          ]);
        } else if (response.content) {
          const assistantMsg = {
            id: `msg-${Date.now()}`,
            role: 'assistant' as const,
            content: response.content,
            timestamp: Date.now(),
            taskId: response.taskId,
          };
          setMessages((prev) => [...prev, assistantMsg]);
          if (sessionId) {
            chatHistory.saveMessage(sessionId, 'assistant', response.content, response.taskId).catch((e) => logError('OrchestratorChat', `Failed to save assistant message: ${e}`));
          }
        }
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        logError('OrchestratorChat', msg);
      } finally {
        setIsLoading(false);
      }
    };

    on(SOCKET_EVENTS.ORCHESTRATOR_RESPONSE, handleOrchestratorResponse);

    return () => {
      if (socket) socket.off(SOCKET_EVENTS.ORCHESTRATOR_RESPONSE, handleOrchestratorResponse);
    };
  }, [socket, on]);

  const sendPrompt = async (prompt: string) => {
    if (!prompt.trim()) return;

    const userMessage: ChatMessage = {
      id: `msg-${Date.now()}`,
      role: 'user',
      content: prompt,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev.slice(-MAX_CHAT_MESSAGES), userMessage]);
    setInputValue('');
    setIsLoading(true);

    logInfo('OrchestratorChat', `Sending prompt: ${prompt.slice(0, 50)}`);

    // Save user message to history
    if (sessionId) {
      try {
        await chatHistory.saveMessage(sessionId, 'user', prompt);
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        logError('OrchestratorChat', `Failed to save user message: ${msg}`);
      }
    }

    emit(SOCKET_EVENTS.ORCHESTRATOR_PROMPT, {
      prompt,
      timestamp: Date.now(),
    });
  };

  const handleTemplateClick = (template: typeof TASK_TEMPLATES[0]) => {
    setExpandedTemplate(expandedTemplate === template.id ? null : template.id);
  };

  const handleSendTemplate = (template: typeof TASK_TEMPLATES[0]) => {
    sendPrompt(template.text);
    setExpandedTemplate(null);
  };

  const clearHistory = () => {
    setMessages([]);
    logInfo('OrchestratorChat', 'Chat history cleared');
    if (sessionId) {
      chatHistory.clearHistory(sessionId).catch((e) => logError('OrchestratorChat', `Failed to clear history: ${e}`));
    }
  };

  const copyMessage = (content: string) => {
    navigator.clipboard.writeText(content);
  };

  return (
    <div className="h-screen flex flex-col bg-white dark:bg-slate-950 border-l border-gray-200 dark:border-gray-800">
      {/* Header */}
      <div className="border-b border-gray-200 dark:border-gray-800 p-4 bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-slate-900 dark:to-slate-800">
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-lg font-bold text-gray-900 dark:text-white">
              🤖 Orchestrator Chat
            </h1>
            <p className="text-xs text-gray-600 dark:text-gray-400 mt-1">
              {connected ? '🟢 Online' : '🔴 Offline'} | {messages.length} üzenet
            </p>
          </div>
          <button
            onClick={clearHistory}
            className="p-2 rounded hover:bg-red-100 dark:hover:bg-red-900 transition text-red-600"
            title="Történet törlése"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 ? (
          <div className="text-center text-gray-500 dark:text-gray-400 py-12">
            <p className="text-sm">Üdvözlöm! 👋</p>
            <p className="text-xs mt-2">Válassz templates-et alul vagy írj egy kérdést.</p>
          </div>
        ) : (
          messages.map((msg) => (
            <div
              key={msg.id}
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-xs p-3 rounded-lg ${
                  msg.role === 'user'
                    ? 'bg-blue-600 text-white rounded-br-none'
                    : 'bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-white rounded-bl-none'
                }`}
              >
                <p className="text-sm break-words">{msg.content}</p>
                <div className="flex justify-between items-center mt-2 gap-2">
                  <span className="text-xs opacity-70">
                    {new Date(msg.timestamp).toLocaleTimeString('hu-HU')}
                  </span>
                  {msg.role === 'assistant' && (
                    <button
                      onClick={() => copyMessage(msg.content)}
                      className="opacity-50 hover:opacity-100 transition"
                      title="Másolás"
                    >
                      <Copy size={14} />
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Templates Section */}
      <div className="border-t border-gray-200 dark:border-gray-800 p-3 bg-gray-50 dark:bg-slate-900 max-h-40 overflow-y-auto">
        <div className="text-xs font-semibold text-gray-700 dark:text-gray-300 mb-2">
          ⚡ Gyors parancsok:
        </div>
        <div className="space-y-2">
          {TASK_TEMPLATES.map((template) => (
            <div key={template.id}>
              <button
                onClick={() => handleTemplateClick(template)}
                className="w-full text-left px-3 py-2 rounded bg-white dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-slate-700 transition text-sm text-gray-900 dark:text-gray-200 border border-gray-200 dark:border-gray-700 flex justify-between items-center"
              >
                <span>{template.label}</span>
                <span className="text-xs">{expandedTemplate === template.id ? '▼' : '▶'}</span>
              </button>
              {expandedTemplate === template.id && (
                <div className="bg-blue-50 dark:bg-blue-900 border border-blue-200 dark:border-blue-800 rounded mt-1 p-2">
                  <p className="text-xs text-gray-700 dark:text-gray-300 mb-2">{template.text}</p>
                  <button
                    onClick={() => handleSendTemplate(template)}
                    className="w-full px-2 py-1 rounded bg-blue-600 text-white text-xs hover:bg-blue-700 transition font-medium"
                  >
                    Küldés
                  </button>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Input */}
      <div className="border-t border-gray-200 dark:border-gray-800 p-4 bg-white dark:bg-slate-900">
        <div className="flex gap-2">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendPrompt(inputValue);
              }
            }}
            placeholder="Írj egy parancsot..."
            disabled={isLoading || !connected}
            className="flex-1 px-3 py-2 rounded border border-gray-300 dark:border-gray-600 dark:bg-slate-800 dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
          />
          <button
            onClick={() => sendPrompt(inputValue)}
            disabled={isLoading || !connected || !inputValue.trim()}
            className="px-3 py-2 rounded bg-blue-600 text-white hover:bg-blue-700 transition disabled:opacity-50 flex items-center gap-2"
            aria-label="Üzenet küldése"
          >
            <Send size={18} />
          </button>
        </div>
        <p className="text-xs text-gray-500 dark:text-gray-400 mt-2">
          💡 Tipp: Enter = Küldés | Shift+Enter = Új sor
        </p>
      </div>
    </div>
  );
};

import { Server, Socket } from "socket.io";
import { logInfo, logError } from "../utils/logger.js";
import { cloudflareClient } from "../agents/cloudflare/CloudflareClient.js";
import { agentManager } from "../agents/AgentManager.js";

/**
 * Register Cloudflare Edge WebSocket event handlers
 *
 * This function sets up real-time WebSocket communication between
 * the Dashboard and Cloudflare Workers AI.
 *
 * Events:
 * - edge:task:submit - Submit a task to the Worker
 * - edge:chat:message - Send a chat message to Worker LLM
 * - edge:status:query - Query task status by taskId
 *
 * @param io - Socket.IO Server instance
 */
export function registerEdgeWebSocketHandlers(io: Server) {
  io.on("connection", (socket: Socket) => {
    logInfo("EdgeWebSocket", `Client connected: ${socket.id}`);

    /**
     * Event: edge:task:submit
     * Client submits a task instruction to the Cloudflare Worker
     *
     * Payload: { instruction: string }
     * Response: edge:task:submitted { taskId, status }
     * Progress: edge:task:progress { taskId, progress, status }
     * Complete: edge:task:complete { taskId, result, status }
     */
    socket.on("edge:task:submit", async (data: { instruction: string }) => {
      try {
        logInfo("EdgeWebSocket", `Task submit: ${data.instruction}`);

        // Call Cloudflare Worker to submit task
        const { taskId } = await cloudflareClient.submitTask(data.instruction);

        // Emit task submitted confirmation
        socket.emit("edge:task:submitted", {
          taskId,
          status: "pending",
          instruction: data.instruction,
        });

        // Poll for progress updates (in future, Worker will push via WebSocket)
        const progressInterval = setInterval(async () => {
          try {
            const status = await cloudflareClient.checkStatus(taskId);

            // Emit progress update
            socket.emit("edge:task:progress", {
              taskId,
              progress: status.progress || 0,
              status: status.status,
              currentStep: status.currentStep,
            });

            // Stop polling when task completes or fails
            if (status.status === "success" || status.status === "error") {
              clearInterval(progressInterval);

              socket.emit("edge:task:complete", {
                taskId,
                result: status.result,
                status: status.status,
                error: status.error,
              });

              logInfo(
                "EdgeWebSocket",
                `Task ${taskId} completed: ${status.status}`,
              );
            }
          } catch (error: any) {
            clearInterval(progressInterval);
            logError("EdgeWebSocket", `Progress poll error: ${error.message}`);
            socket.emit("edge:task:error", {
              taskId,
              error: error.message,
            });
          }
        }, 2000); // Poll every 2 seconds

        // Cleanup interval on disconnect
        socket.on("disconnect", () => {
          clearInterval(progressInterval);
        });
      } catch (error: any) {
        logError("EdgeWebSocket", `Task submit error: ${error.message}`);
        socket.emit("edge:task:error", {
          error: error.message,
        });
      }
    });

    /**
     * Event: edge:chat:message
     * Client sends a chat message to the Cloudflare Worker LLM
     *
     * Payload: { instruction: string, history?: any[] }
     * Response: edge:chat:response { response }
     * Error: edge:chat:error { error }
     */
    socket.on(
      "edge:chat:message",
      async (data: { instruction: string; history?: any[] }) => {
        try {
          logInfo("EdgeWebSocket", `Chat message: ${data.instruction}`);

          // Call Cloudflare Worker to process chat
          const response = await cloudflareClient.chat(
            data.instruction,
            data.history,
          );

          // Emit chat response
          socket.emit("edge:chat:response", {
            response,
            timestamp: Date.now(),
          });
        } catch (error: any) {
          logError("EdgeWebSocket", `Chat error: ${error.message}`);
          socket.emit("edge:chat:error", {
            error: error.message,
          });
        }
      },
    );

    /**
     * Event: edge:status:query
     * Client queries the status of a specific task
     *
     * Payload: { taskId: string }
     * Response: edge:status:response { taskId, status, result, progress }
     * Error: edge:status:error { error }
     */
    socket.on("edge:status:query", async (data: { taskId: string }) => {
      try {
        logInfo("EdgeWebSocket", `Status query: ${data.taskId}`);

        // Query task status from Cloudflare Worker
        const status = await cloudflareClient.checkStatus(data.taskId);

        // Emit status response
        socket.emit("edge:status:response", {
          taskId: data.taskId,
          status: status.status,
          result: status.result,
          progress: status.progress,
          currentStep: status.currentStep,
          error: status.error,
        });
      } catch (error: any) {
        logError("EdgeWebSocket", `Status query error: ${error.message}`);
        socket.emit("edge:status:error", {
          taskId: data.taskId,
          error: error.message,
        });
      }
    });

    /**
     * Event: disconnect
     * Clean up resources when client disconnects
     */
    socket.on("disconnect", () => {
      logInfo("EdgeWebSocket", `Client disconnected: ${socket.id}`);
    });
  });

  logInfo("EdgeWebSocket", "Edge WebSocket handlers registered ✅");
}

/**
 * Register CEAN Orchestrator Chat WebSocket handlers
 *
 * Events:
 * - cean:orchestrator:prompt - User sends prompt to OrchestratorAgent
 * - cean:orchestrator:response - Agent sends response back to client
 *
 * @param io - Socket.IO Server instance
 */
export function registerCEANWebSocketHandlers(io: Server) {
  io.on("connection", (socket: Socket) => {
    /**
     * Event: cean:orchestrator:prompt
     * Client sends a prompt to the Orchestrator Agent
     *
     * Payload: { prompt: string, timestamp: number }
     * Response: cean:orchestrator:response { content, taskId?, error? }
     */
    socket.on(
      "cean:orchestrator:prompt",
      async (data: { prompt: string; timestamp: number }) => {
        try {
          logInfo("CEANChat", `Prompt received: ${data.prompt.slice(0, 50)}`);

          // Get OrchestratorAgent and execute prompt
          const orchestrator = agentManager.getAgent("OrchestratorAgent");
          if (!orchestrator) {
            throw new Error("OrchestratorAgent not found");
          }

          const result = await orchestrator.execute(data.prompt);

          // Extract response and taskId from result
          const responseContent =
            typeof result === "string"
              ? result
              : typeof result === "object" && result !== null
                ? (result as Record<string, unknown>).data || JSON.stringify(result)
                : String(result);

          const taskId = (result as Record<string, unknown>)?.taskId || undefined;

          logInfo("CEANChat", `Response sent (${String(responseContent).length} chars)`);

          // Emit response back to client
          socket.emit("cean:orchestrator:response", {
            content: responseContent,
            taskId,
            timestamp: Date.now(),
          });
        } catch (error: unknown) {
          const errorMsg =
            error instanceof Error ? error.message : String(error);
          logError("CEANChat", errorMsg);

          socket.emit("cean:orchestrator:response", {
            error: errorMsg,
            timestamp: Date.now(),
          });
        }
      },
    );
  });

  logInfo("CEANChat", "CEAN Orchestrator WebSocket handlers registered ✅");
}

/**
 * Register Fleet Management WebSocket handlers
 *
 * Events broadcasted to all connected clients:
 * - fleet_scaled - When a fleet is scaled up/down
 * - worker_status_changed - When a worker status changes
 * - metrics_updated - When metrics are updated
 *
 * @param io - Socket.IO Server instance
 */
export function registerFleetWebSocketHandlers(io: Server) {
  io.on("connection", (socket: Socket) => {
    logInfo("FleetWS", `Fleet client connected: ${socket.id}`);

    /**
     * Event: fleet_scaled
     * Emitted when a fleet scaling event occurs
     * Broadcasted to ALL clients
     *
     * Payload:
     * {
     *   fleet_id: string
     *   old_worker_count: number
     *   new_worker_count: number
     *   direction: 'up' | 'down'
     *   timestamp: number
     * }
     */
    socket.on(
      "broadcast:fleet_scaled",
      (data: {
        fleet_id: string;
        old_worker_count: number;
        new_worker_count: number;
        direction: "up" | "down";
        timestamp: number;
      }) => {
        logInfo(
          "FleetWS",
          `Fleet ${data.fleet_id} scaled ${data.direction}: ${data.old_worker_count} → ${data.new_worker_count} workers`
        );

        // Broadcast to all clients
        io.emit("fleet_scaled", data);
      }
    );

    /**
     * Event: worker_status_changed
     * Emitted when a worker status changes
     * Broadcasted to ALL clients
     *
     * Payload:
     * {
     *   worker_id: string
     *   fleet_id: string
     *   status: 'healthy' | 'degraded' | 'offline'
     *   latency_p95?: number
     *   error_rate?: number
     *   timestamp: number
     * }
     */
    socket.on(
      "broadcast:worker_status_changed",
      (data: {
        worker_id: string;
        fleet_id: string;
        status: "healthy" | "degraded" | "offline";
        latency_p95?: number;
        error_rate?: number;
        timestamp: number;
      }) => {
        logInfo("FleetWS", `Worker ${data.worker_id} status: ${data.status}`);

        // Broadcast to all clients
        io.emit("worker_status_changed", data);
      }
    );

    /**
     * Event: metrics_updated
     * Emitted when fleet or worker metrics are updated
     * Broadcasted to ALL clients
     *
     * Payload:
     * {
     *   fleet_id?: string
     *   worker_id?: string
     *   avg_latency?: number
     *   p95_latency?: number
     *   p99_latency?: number
     *   error_rate?: number
     *   rps?: number
     *   timestamp: number
     * }
     */
    socket.on(
      "broadcast:metrics_updated",
      (data: {
        fleet_id?: string;
        worker_id?: string;
        avg_latency?: number;
        p95_latency?: number;
        p99_latency?: number;
        error_rate?: number;
        rps?: number;
        total_workers?: number;
        healthy_workers?: number;
        timestamp: number;
      }) => {
        logInfo(
          "FleetWS",
          `Metrics updated${data.fleet_id ? ` (fleet: ${data.fleet_id})` : data.worker_id ? ` (worker: ${data.worker_id})` : ""}`
        );

        // Broadcast to all clients
        io.emit("metrics_updated", data);
      }
    );

    socket.on("disconnect", () => {
      logInfo("FleetWS", `Fleet client disconnected: ${socket.id}`);
    });
  });

  logInfo("FleetWS", "Fleet Management WebSocket handlers registered ✅");
}

/**
 * CloudflareClient - WebSocket-aware wrapper for EdgeProxyAgent
 *
 * This class provides a simplified API for interacting with Cloudflare Workers
 * from the WebSocket event handlers. It wraps EdgeProxyAgent and provides
 * methods optimized for real-time communication.
 *
 * @author Brunella Core Team
 * @version 1.0.0
 */

import { EdgeProxyAgent } from "../EdgeProxyAgent.js";
import { AgentContext } from "../BaseAgent.js";
import { logInfo, logError } from "../../utils/logger.js";

// ============================================================================
// INTERFACES
// ============================================================================

interface TaskSubmitResult {
  taskId: string;
  status: "pending" | "running" | "success" | "error";
}

interface TaskStatusResult {
  status: "pending" | "running" | "success" | "error";
  progress?: number;
  currentStep?: string;
  result?: any;
  error?: string;
}

interface ChatResponse {
  response: string;
  model?: string;
}

// ============================================================================
// CLIENT IMPLEMENTATION
// ============================================================================

class CloudflareClientClass {
  private edgeAgent: EdgeProxyAgent;
  private initialized = false;

  constructor() {
    this.edgeAgent = new EdgeProxyAgent();
  }

  /**
   * Initialize the Cloudflare client
   * This should be called once during server startup
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;

    try {
      await this.edgeAgent.initialize();
      this.initialized = true;
      logInfo("CloudflareClient", "Initialized successfully");
    } catch (error: any) {
      logError("CloudflareClient", `Initialization failed: ${error.message}`);
      throw error;
    }
  }

  /**
   * Submit a task to the Cloudflare Worker
   *
   * @param instruction - Task instruction text
   * @returns Task ID and initial status
   */
  async submitTask(instruction: string): Promise<TaskSubmitResult> {
    if (!this.initialized) {
      await this.initialize();
    }

    try {
      const context: AgentContext = {
        task: instruction,
        context: {},
      };

      const result = await this.edgeAgent.submitTask(context);

      if (!result.success) {
        throw new Error(result.message || "Task submission failed");
      }

      // Extract task ID from result data
      const taskId =
        (result.data as any)?.task?.taskId || this.generateTaskId();

      return {
        taskId,
        status: "pending",
      };
    } catch (error: any) {
      logError("CloudflareClient", `submitTask error: ${error.message}`);
      throw error;
    }
  }

  /**
   * Check the status of a task
   *
   * @param taskId - Task ID to query
   * @returns Task status with progress and result
   */
  async checkStatus(taskId: string): Promise<TaskStatusResult> {
    if (!this.initialized) {
      await this.initialize();
    }

    try {
      const taskStatus = await this.edgeAgent.getTaskStatus(taskId);

      if (!taskStatus) {
        return {
          status: "error",
          error: "Task not found",
        };
      }

      return {
        status: taskStatus.status as any,
        result: taskStatus.result,
        // Mock progress calculation based on status
        progress:
          taskStatus.status === "completed"
            ? 100
            : taskStatus.status === "pending"
              ? 0
              : 50,
        currentStep:
          taskStatus.status === "dispatched"
            ? "Processing..."
            : taskStatus.status,
      };
    } catch (error: any) {
      logError("CloudflareClient", `checkStatus error: ${error.message}`);
      return {
        status: "error",
        error: error.message,
      };
    }
  }

  /**
   * Send a chat message to the Cloudflare Worker AI
   *
   * @param instruction - Chat message text
   * @param history - Optional conversation history
   * @returns Chat response from Worker AI
   */
  async chat(instruction: string, history?: any[]): Promise<ChatResponse> {
    if (!this.initialized) {
      await this.initialize();
    }

    try {
      // For now, use submitTask with a special chat format
      // In future, this will be a dedicated /chat endpoint on the Worker
      const context: AgentContext = {
        task: `[CHAT] ${instruction}`,
        context: { history },
      };

      const result = await this.edgeAgent.submitTask(context);

      if (!result.success) {
        throw new Error(result.message || "Chat request failed");
      }

      // Extract response from result
      const response =
        (result.data as any)?.task?.result ||
        result.message ||
        "Response received";

      return {
        response,
        model: "cloudflare-worker-ai",
      };
    } catch (error: any) {
      logError("CloudflareClient", `chat error: ${error.message}`);
      throw error;
    }
  }

  /**
   * Check if the Cloudflare Worker is healthy
   *
   * @returns Health status
   */
  async isHealthy(): Promise<boolean> {
    if (!this.initialized) {
      await this.initialize();
    }

    return this.edgeAgent.isEdgeHealthy();
  }

  /**
   * Get health status details
   */
  getHealthStatus() {
    return this.edgeAgent.getHealth();
  }

  /**
   * Shutdown the client gracefully
   */
  async shutdown(): Promise<void> {
    if (this.initialized) {
      await this.edgeAgent.shutdown();
      this.initialized = false;
      logInfo("CloudflareClient", "Shutdown complete");
    }
  }

  // --------------------------------------------------------------------------
  // PRIVATE HELPERS
  // --------------------------------------------------------------------------

  private generateTaskId(): string {
    return `task_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
  }
}

// Export singleton instance
export const cloudflareClient = new CloudflareClientClass();

/**
 * EdgeProxyAgent - Cloudflare Edge Kommunikáció
 * 
 * Felelősségek:
 * 1. Cloudflare Workers kommunikáció
 * 2. Task routing edge-re
 * 3. Fallback kezelés (ha tunnel nem elérhető)
 * 4. Távoli állapot szinkronizálás
 * 
 * @author Brunella Core Team
 * @version 1.0.0
 */

import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';
import { getGlobalDb } from '../utils/globalDb.js';

// ============================================================================
// INTERFACES
// ============================================================================

interface EdgeConfig {
  workerUrl: string;
  tunnelEnabled: boolean;
  fallbackToLocal: boolean;
  healthCheckInterval: number;
  apiKey?: string;
  tunnelUrl?: string;
  tunnelN8nUrl?: string;
  tunnelBrowserUrl?: string;
  tunnelDashboardUrl?: string;
}

interface EdgeHealth {
  edge: 'healthy' | 'degraded' | 'offline';
  tunnel: 'connected' | 'disconnected';
  latency: number;
  lastCheck: string;
}

interface EdgeTask {
  taskId: string;
  type: string;
  status: 'pending' | 'dispatched' | 'completed' | 'failed';
  payload: any;
  result?: any;
  createdAt: string;
  completedAt?: string;
}

// ============================================================================
// CONSTANTS
// ============================================================================

const DEFAULT_CONFIG: EdgeConfig = {
  workerUrl: process.env.CLOUDFLARE_WORKER_URL || 'https://bas-orchestrator.workers.dev',
  tunnelEnabled: process.env.CLOUDFLARE_TUNNEL_ENABLED === 'true',
  fallbackToLocal: true,
  healthCheckInterval: 30000,
  tunnelUrl: process.env.CLOUDFLARE_TUNNEL_URL,
  tunnelN8nUrl: process.env.CLOUDFLARE_TUNNEL_N8N_URL,
  tunnelBrowserUrl: process.env.CLOUDFLARE_TUNNEL_BROWSER_URL,
  tunnelDashboardUrl: process.env.CLOUDFLARE_TUNNEL_DASHBOARD_URL
};

// ============================================================================
// AGENT IMPLEMENTATION
// ============================================================================

export class EdgeProxyAgent extends BaseAgent {
  name = 'EdgeProxy';
  description = 'Cloudflare Edge kommunikáció és task routing';
  role = 'Edge Proxy & Remote Access';

  private config: EdgeConfig;
  private health: EdgeHealth;
  private healthCheckTimer?: NodeJS.Timeout;

  constructor(config?: Partial<EdgeConfig>) {
    super();
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.health = {
      edge: 'offline',
      tunnel: 'disconnected',
      latency: -1,
      lastCheck: ''
    };
  }

  // --------------------------------------------------------------------------
  // LIFECYCLE
  // --------------------------------------------------------------------------

  async initialize(): Promise<void> {
    logInfo(this.name, `Inicializálás: ${this.config.workerUrl}`);

    // Kezdeti health check
    await this.checkHealth();

    // Periodikus health check
    if (this.config.healthCheckInterval > 0) {
      this.healthCheckTimer = setInterval(
        () => this.checkHealth(),
        this.config.healthCheckInterval
      );
    }
  }

  async shutdown(): Promise<void> {
    if (this.healthCheckTimer) {
      clearInterval(this.healthCheckTimer);
    }
    logInfo(this.name, 'Leállítva');
  }

  // --------------------------------------------------------------------------
  // MAIN EXECUTION
  // --------------------------------------------------------------------------

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = context.task?.toLowerCase() || '';
    setAgentStatus(this.name, 'working', task);

    try {
      // Command routing
      if (task.includes('health') || task.includes('status')) {
        return await this.getEdgeStatus();
      }

      if (task.includes('submit') || task.includes('task')) {
        return await this.submitTask(context);
      }

      if (task.includes('sync') || task.includes('szinkron')) {
        return await this.syncWithEdge();
      }

      if (task.includes('test') || task.includes('teszt')) {
        return await this.runEdgeTest();
      }

      // Default: show help
      return this.showHelp();

    } catch (error) {
      logError(this.name, `Hiba: ${error}`);
      setAgentStatus(this.name, 'error');
      return {
        success: false,
        message: `EdgeProxy hiba: ${error}`,
        data: null
      };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

  // --------------------------------------------------------------------------
  // CORE FUNCTIONS
  // --------------------------------------------------------------------------

  /**
   * Edge health check
   */
  async checkHealth(): Promise<EdgeHealth> {
    const startTime = Date.now();

    try {
      const response = await fetch(`${this.config.workerUrl}/health`, {
        method: 'GET',
        headers: this.getHeaders(),
        signal: AbortSignal.timeout(10000)
      });

      const latency = Date.now() - startTime;

      if (response.ok) {
        const data = await response.json() as any;
        this.health = {
          edge: 'healthy',
          tunnel: data.tunnel || 'unknown',
          latency,
          lastCheck: new Date().toISOString()
       };
      } else {
        this.health.edge = 'degraded';
        this.health.latency = latency;
      }
    } catch (error) {
      this.health = {
        edge: 'offline',
        tunnel: 'disconnected',
        latency: -1,
        lastCheck: new Date().toISOString()
      };
    }

    return this.health;
  }

  /**
   * Edge státusz lekérdezése
   */
  private async getEdgeStatus(): Promise<AgentResult> {
    logInfo(this.name, 'Edge státusz lekérdezése...');

    await this.checkHealth();

    const statusIcon = this.health.edge === 'healthy' ? '✅' :
      this.health.edge === 'degraded' ? '⚠️' : '❌';

    const report = `
# 🌐 Cloudflare Edge Státusz

**Worker URL:** ${this.config.workerUrl}
**Státusz:** ${statusIcon} ${this.health.edge}
**Tunnel:** ${this.health.tunnel === 'connected' ? '✅' : '❌'} ${this.health.tunnel}
**Latency:** ${this.health.latency}ms
**Utolsó ellenőrzés:** ${this.health.lastCheck}

## Konfiguráció
- **Tunnel engedélyezve:** ${this.config.tunnelEnabled}
- **Lokális fallback:** ${this.config.fallbackToLocal}
- **Health check intervallum:** ${this.config.healthCheckInterval}ms
`;

    return {
      success: true,
      message: `Edge státusz: ${this.health.edge}`,
      data: { health: this.health, report }
    };
  }

  /**
   * Task beküldése az edge-re
   */
  async submitTask(context: AgentContext): Promise<AgentResult> {
    logInfo(this.name, 'Task beküldése az edge-re...');

    // Edge elérhetőség ellenőrzése
    if (this.health.edge === 'offline') {
      await this.checkHealth();
    }

    if (this.health.edge === 'offline' && this.config.fallbackToLocal) {
      logInfo(this.name, 'Edge offline, lokális fallback...');
      return {
        success: false,
        message: 'Edge nem elérhető, lokális feldolgozás szükséges',
        data: { fallback: true }
      };
    }

    try {
      const payload: any = {
        instruction: context.task,
        context: context.context || {},
        source: 'brunella-core',
        timestamp: new Date().toISOString()
      };

      // Add tunnel callback URLs if available
      if (this.config.tunnelEnabled && this.config.tunnelUrl) {
        payload.callbackUrls = {
          api: this.config.tunnelUrl,
          n8n: this.config.tunnelN8nUrl,
          browser: this.config.tunnelBrowserUrl,
          dashboard: this.config.tunnelDashboardUrl
       };
        logInfo(this.name, `Tunnel callback URL-ek hozzáadva: ${this.config.tunnelUrl}`);
      }

      const response = await fetch(`${this.config.workerUrl}/task`, {
        method: 'POST',
        headers: this.getHeaders(),
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(30000)
      });

      if (!response.ok) {
        throw new Error(`Edge error: ${response.status}`);
      }

      const result = await response.json() as EdgeTask;

      logInfo(this.name, `Task beküldve: ${result.taskId}`);

      return {
        success: true,
        message: `Task sikeresen beküldve: ${result.taskId}`,
        data: { task: result }
      };

    } catch (error) {
      logError(this.name, `Task beküldés sikertelen: ${error}`);

      if (this.config.fallbackToLocal) {
       return {
         success: false,
          message: `Edge hiba, lokális fallback: ${error}`,
          data: { fallback: true, error: String(error) }
       };
      }

      throw error;
    }
  }

  /**
   * Task státusz lekérdezése
   */
  async getTaskStatus(taskId: string): Promise<EdgeTask | null> {
    try {
      const response = await fetch(`${this.config.workerUrl}/status/${taskId}`, {
        method: 'GET',
        headers: this.getHeaders(),
        signal: AbortSignal.timeout(10000)
      });

      if (response.ok) {
        return await response.json() as EdgeTask;
      }

      return null;
    } catch {
      return null;
    }
  }

  /**
   * Szinkronizálás az edge-gel
   */
  private async syncWithEdge(): Promise<AgentResult> {
    logInfo(this.name, 'Szinkronizálás az edge-gel...');

    // Health check
    await this.checkHealth();

    if (this.health.edge === 'offline') {
      return {
        success: false,
        message: 'Edge nem elérhető',
        data: { health: this.health }
      };
    }

    try {
      const db = getGlobalDb();
      let syncedCount = 0;
      let updatedCount = 0;

      // 1. Fetch history from Cloudflare Worker
      const response = await fetch(`${this.config.workerUrl}/history?limit=50`, {
        method: 'GET',
        headers: this.getHeaders(),
        signal: AbortSignal.timeout(10000)
      });

      if (response.ok) {
        const data = await response.json() as { tasks: any[] };
        const tasks = data.tasks || [];

        const stmt = db.prepare(`
          INSERT INTO edge_tasks (task_id, type, status, payload, result, created_at, completed_at, synced_at)
          VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'))
          ON CONFLICT(task_id) DO UPDATE SET
            status = excluded.status,
            result = excluded.result,
            completed_at = excluded.completed_at,
            synced_at = datetime('now')
        `);

        const insertMany = db.transaction((tasks: any[]) => {
          for (const task of tasks) {
            stmt.run(
              task.taskId || task.id,
              task.type || 'unknown',
              task.status,
              JSON.stringify(task.payload || {}),
              JSON.stringify(task.result || null),
              task.createdAt || new Date().toISOString(),
              task.completedAt || null
           );
          }
        });

        insertMany(tasks);
        syncedCount = tasks.length;
      }

      // 2. Update pending tasks status
      const pendingTasks = db.prepare("SELECT task_id FROM edge_tasks WHERE status IN ('pending', 'dispatched')").all() as { task_id: string }[];

      const updateStmt = db.prepare(`
        UPDATE edge_tasks
        SET status = ?, result = ?, completed_at = ?, synced_at = datetime('now')
        WHERE task_id = ?
      `);

      for (const { task_id } of pendingTasks) {
        const taskStatus = await this.getTaskStatus(task_id);
        if (taskStatus) {
          updateStmt.run(
            taskStatus.status,
            JSON.stringify(taskStatus.result || null),
            taskStatus.completedAt || null,
            task_id
          );
          updatedCount++;
        }
      }

      logInfo(this.name, `Szinkronizálás kész: ${syncedCount} új/frissített, ${updatedCount} státusz ellenőrzött`);

      return {
        success: true,
        message: 'Szinkronizálás befejezve',
        data: {
          health: this.health,
          stats: { syncedCount, updatedCount }
        }
      };

    } catch (error) {
      logError(this.name, `Szinkronizálási hiba: ${error}`);
      return {
        success: false,
        message: `Szinkronizálási hiba: ${error}`,
        data: { health: this.health }
      };
    }
  }

  /**
   * Edge kapcsolat tesztelése
   */
  private async runEdgeTest(): Promise<AgentResult> {
    logInfo(this.name, 'Edge kapcsolat tesztelése...');

    const tests = [
      { name: 'Health Check', fn: () => this.checkHealth() },
      { name: 'Task Submit', fn: () => this.submitTask({ task: 'test', context: {} } as AgentContext) },
    ];

    const results: Array<{ test: string; success: boolean; duration: number; error?: string }> = [];

    for (const test of tests) {
      const start = Date.now();
      try {
        await test.fn();
        results.push({
          test: test.name,
          success: true,
          duration: Date.now() - start
        });
      } catch (error) {
        results.push({
          test: test.name,
         success: false,
          duration: Date.now() - start,
          error: String(error)
        });
      }
    }

    const allPassed = results.every(r => r.success);

    return {
      success: allPassed,
      message: `Edge teszt: ${allPassed ? 'PASSED' : 'FAILED'}`,
      data: { results }
    };
  }

  // --------------------------------------------------------------------------
  // HELPER FUNCTIONS
  // --------------------------------------------------------------------------

  private getHeaders(): HeadersInit {
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
      'User-Agent': 'Brunella-Core/1.0'
    };

    if (this.config.apiKey) {
      headers['X-BAS-API-Key'] = this.config.apiKey;
    }

    return headers;
  }

  private showHelp(): AgentResult {
    const helpText = `
# EdgeProxy Agent - Súgó

## Elérhető parancsok:

| Parancs | Leírás |
|---------|--------|
| \`health\` / \`status\` | Edge státusz lekérdezése |
| \`submit [task]\` | Task beküldése az edge-re |
| \`sync\` | Szinkronizálás az edge-gel |
| \`test\` | Edge kapcsolat tesztelése |

## Konfiguráció (.env):

\`\`\`
CLOUDFLARE_WORKER_URL=https://bas-orchestrator.workers.dev
CLOUDFLARE_TUNNEL_ENABLED=true
CLOUDFLARE_API_KEY=your-api-key
\`\`\`
`;

    return {
      success: true,
      message: 'EdgeProxy súgó',
      data: { help: helpText }
    };
  }

  // --------------------------------------------------------------------------
  // PUBLIC API
  // --------------------------------------------------------------------------

  isEdgeHealthy(): boolean {
    return this.health.edge === 'healthy';
  }

  isTunnelConnected(): boolean {
    return this.health.tunnel === 'connected';
  }

  getHealth(): EdgeHealth {
    return { ...this.health };
